from __future__ import annotations

def contact_page(*, SERVICES, SERVICE_DISPLAY_ORDER, hero, PHONE_LINK, PHONE_DISPLAY, EMAIL, GOOGLE_REVIEW, section_heading, page) -> str:
    options = "".join(
        f'<option value="{SERVICES[slug]["name"]}">{SERVICES[slug]["name"]}</option>'
        for slug in SERVICE_DISPLAY_ORDER
    )
    body = f"""
    {hero("project-129.jpg", "Completed kitchen renovation", "Contact Hekman Home Services", "Tell us what you want to change.", "A short description and the project location are enough to begin. Photos can follow when we reply.", small=True, position="50% 58%")}
    <main id="main">
      <section class="section section-paper" id="quote"><div class="wrap contact-layout"><div class="contact-intro reveal"><p class="eyebrow">Request a quote</p><h2>Start with what you know.</h2><p>You do not need every finish or measurement decided. Tell us what is not working, what you would like the space to become and where the property is located.</p><div class="contact-direct"><h3>Prefer direct contact?</h3><a href="tel:{PHONE_LINK}"><small>Call or text</small><strong>{PHONE_DISPLAY}</strong></a><a href="mailto:{EMAIL}"><small>Email</small><strong>{EMAIL}</strong></a><div><small>Service area</small><strong>London &amp; St. Thomas</strong></div><a href="{GOOGLE_REVIEW}" rel="noopener noreferrer" target="_blank" aria-label="Leave Hekman Home Services a review on Google (opens in a new tab)"><small>Already worked with us?</small><strong>Leave a Google review</strong></a></div></div>
      <form class="quote-form reveal" id="quote-form" action="/api/quote/" method="post" aria-labelledby="quote-form-title" aria-describedby="quote-privacy-note"><div class="form-heading"><h3 id="quote-form-title">Project enquiry</h3><small>Fields marked * are required</small></div><div class="quote-success native-submit-message" id="quote-sent" tabindex="-1" role="status"><strong>Thank you—your enquiry is sent.</strong><p>Steph and Rene will review the details and get back to you directly.</p></div><div class="quote-handoff native-submit-message" id="quote-error" tabindex="-1" role="alert"><strong>We could not send it online.</strong><p>Please try the form again, or call, text or email us directly.</p></div><div class="form-grid"><label>Name *<input name="name" autocomplete="name" minlength="2" maxlength="100" required></label><label>Project location *<input name="location" autocomplete="address-level2" placeholder="London, Byron, St. Thomas…" minlength="2" maxlength="160" required></label></div><fieldset aria-describedby="contact-help"><legend>How should we reach you? *</legend><p id="contact-help">Enter a phone number, an email address, or both.</p><div class="form-grid"><label>Phone<input name="phone" type="tel" autocomplete="tel" inputmode="tel" maxlength="40"></label><label>Email<input name="email" type="email" autocomplete="email" maxlength="254"></label></div></fieldset><div class="form-grid"><label>Project type<select name="service"><option value="">Choose one</option>{options}<option value="Multiple services / other">Multiple services / other</option></select></label><label>Preferred timing<input name="timing" placeholder="Flexible, this fall, as soon as possible…" maxlength="120"></label></div><label>Project details *<textarea name="message" placeholder="What would you like repaired, renovated or changed?" minlength="10" maxlength="4000" required></textarea></label><label class="form-trap" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><input type="hidden" name="submissionId" data-submission-id><p class="form-error" data-form-error role="alert" aria-live="assertive"></p><p class="form-note form-note-before" id="quote-privacy-note"><strong>Your enquiry will be sent directly to Hekman Home Services.</strong> We use these details only to respond to and assess your project. Please do not include financial, health or other sensitive information. Photos can be shared by email after we reply. <a href="/privacy/">Read our privacy notice.</a></p><button class="button button-primary" type="submit" data-quote-submit><span data-submit-label>Send enquiry</span> <span aria-hidden="true">↗</span></button><div class="quote-success" data-quote-success hidden tabindex="-1" role="status" aria-live="polite"><strong>Thank you—your enquiry is sent.</strong><p>Steph and Rene will review the details and get back to you directly. If you have photos ready, you can email them to <a href="mailto:{EMAIL}">{EMAIL}</a>.</p></div><div class="quote-handoff" data-quote-handoff hidden tabindex="-1"><strong>We could not send it online.</strong><p>Your details are still here. Try again, or use one of the direct options below.</p><div class="quote-handoff-actions"><a class="button button-primary" data-quote-email href="mailto:{EMAIL}">Open draft email</a><button class="button button-ghost" type="button" data-copy-quote>Copy project details</button></div><p class="quote-copy-status" data-copy-status aria-live="polite"></p><div class="quote-fallback-links"><a href="mailto:{EMAIL}">Email {EMAIL}</a><a href="tel:{PHONE_LINK}">Call {PHONE_DISPLAY}</a><a href="sms:{PHONE_LINK}">Text {PHONE_DISPLAY}</a></div></div><noscript><p class="form-note">This form can still send securely without JavaScript. You can also email {EMAIL}, call {PHONE_DISPLAY}, or text {PHONE_DISPLAY} directly.</p></noscript></form></div></section>
      <section class="section section-charcoal"><div class="wrap">{section_heading("What happens next", "A useful first conversation starts with context.", "Sharing a few details helps us understand the likely scope before arranging the next step.")}<ol class="process-grid compact-process"><li class="reveal"><h3>Describe the project</h3><p>Include the location, room and result you have in mind.</p></li><li class="reveal"><h3>Share photos</h3><p>When we reply, you can email wide views and closer images of the affected areas.</p></li><li class="reveal"><h3>Connect</h3><p>We review the information and discuss the appropriate next step.</p></li></ol></div></section>
    </main>"""
    return page("Contact Hekman Home Services | Request a Quote", "Send a renovation or repair enquiry directly to Hekman Home Services Inc. in London, Ontario, or call 519-808-3312.", "/contact/", "project-129.jpg", "contact", body, "contact-page", image_alt="Completed London kitchen renovation with an island and pendant lighting")
def not_found_page(*, page) -> str:
    body = f"""
    <main id="main" class="not-found">
      <img src="/project-132.jpg" alt="" aria-hidden="true">
      <div class="not-found-shade"></div>
      <div class="not-found-content"><p class="eyebrow">404 · Page not found</p><h1>This page needs a little repair.</h1><p>The address may have changed, but the rest of the site is ready to explore.</p><div class="button-row"><a class="button button-primary" href="/">Return Home</a><a class="button button-ghost" href="/services/">Explore Services</a></div></div>
    </main>"""
    return page("Page Not Found | Hekman Home Services", "The requested page could not be found.", "/404.html", "project-132.jpg", "", body, "error-page", indexable=False)
def redirect_stub(destination: str, title: str, *, BASE_URL) -> str:
    canonical = f"{BASE_URL}{destination}"
    return f"""<!doctype html>
    <html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title}</title><meta name="robots" content="noindex"><link rel="canonical" href="{canonical}"><meta http-equiv="refresh" content="0; url={destination}"></head><body><p>This page has moved to <a href="{destination}">{destination}</a>.</p></body></html>"""
